import { readFile, writeFile } from "node:fs/promises";
import { createWorkspace, createForks } from "@tigrisdata/agent-kit";
import { put, get } from "@tigrisdata/storage";

function normalizeBucketName(name: string): string {
  return name.toLowerCase().replace(/[^a-z0-9.-]/g, '-');
}

async function main() {
  const trialIdRaw = await readFile("/logs/artifacts/trial_id", "utf-8");
  const trialId = trialIdRaw.trim();
  const workspaceName = normalizeBucketName(`harbor-ro-${trialId}`);

  console.log(`Creating workspace: ${workspaceName}`);
  const { data: wsData, error: wsError } = await createWorkspace(workspaceName, {
    ttl: { days: 1 },
    enableSnapshots: true,
    credentials: { role: "Editor" }
  });

  if (wsError) {
    console.error("Failed to create workspace:", wsError);
    process.exit(1);
  }
  if (!wsData?.credentials) {
    console.error("No credentials returned for workspace");
    process.exit(1);
  }

  const editorCreds = wsData.credentials;
  const editorBucket = wsData.bucket;

  console.log(`Writing notes/welcome.txt to editor bucket: ${editorBucket}`);
  const { error: putError } = await put("notes/welcome.txt", "hello readonly", {
    config: {
      bucket: editorBucket,
      accessKeyId: editorCreds.accessKeyId,
      secretAccessKey: editorCreds.secretAccessKey
    }
  });

  if (putError) {
    console.error("Failed to write to editor bucket:", putError);
    process.exit(1);
  }

  const forkPrefix = normalizeBucketName(`harbor-ro-${trialId}-readonly`);
  console.log(`Creating fork with prefix: ${forkPrefix}`);

  const { data: forkData, error: forkError } = await createForks(editorBucket, 1, {
    prefix: forkPrefix,
    credentials: { role: "ReadOnly" }
  });

  if (forkError) {
    console.error("Failed to create forks:", forkError);
    process.exit(1);
  }
  if (!forkData?.forks || forkData.forks.length === 0 || !forkData.forks[0].credentials) {
    console.error("No forks or credentials returned");
    process.exit(1);
  }

  const fork = forkData.forks[0];
  const readOnlyCreds = fork.credentials!;
  const forkBucket = fork.bucket;

  console.log(`Attempting forbidden write to fork bucket: ${forkBucket}`);
  const { error: forbiddenError } = await put("notes/forbidden.txt", "should be rejected", {
    config: {
      bucket: forkBucket,
      accessKeyId: readOnlyCreds.accessKeyId,
      secretAccessKey: readOnlyCreds.secretAccessKey
    }
  });

  if (!forbiddenError) {
    console.error("Expected forbidden write to fail, but it succeeded");
    process.exit(1);
  }

  console.log("Forbidden write failed as expected. Capturing error...");
  const denialStr = JSON.stringify(forbiddenError, Object.getOwnPropertyNames(forbiddenError)) + " " + String(forbiddenError.message) + " " + (forbiddenError.cause ? JSON.stringify(forbiddenError.cause, Object.getOwnPropertyNames(forbiddenError.cause)) : "");
  await writeFile("/home/user/tigris-task/write-denial.log", denialStr, "utf-8");

  console.log(`Attempting readback from fork bucket: ${forkBucket}`);
  const { data: readData, error: readError } = await get("notes/welcome.txt", "string", {
    config: {
      bucket: forkBucket,
      accessKeyId: readOnlyCreds.accessKeyId,
      secretAccessKey: readOnlyCreds.secretAccessKey
    }
  });

  if (readError) {
    console.error("Failed to read from fork bucket:", readError);
    process.exit(1);
  }
  if (!readData) {
    console.error("No data returned from read");
    process.exit(1);
  }

  await writeFile("/home/user/tigris-task/readback.txt", readData, "utf-8");
  console.log("Success.");
}

main().catch(err => {
  console.error("Unhandled error:", err);
  process.exit(1);
});
